    public partial class frmSTAPartner : FormBase, IForm
    {
        #region Consts
        public const string PERMISSION_ADD = "STA_Partner_Add";
        public const string PERMISSION_DELETE = "STA_Partner_Delete";
        public const string PERMISSION_EDIT = "STA_Partner_Edit";
        public const string PERMISSION_VIEW = "STA_Partner_View";

        #endregion

        #region Variables

        DataTable dtbData;
        bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmSTAPartner _instance = null;

        public static frmSTAPartner Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmSTAPartner();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion


        public frmSTAPartner()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            gvData.OptionsView.NewItemRowPosition = UserSession.HasPermission(PERMISSION_ADD) ? DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.Top : DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.None;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                ModifyGrid();
            }
        }

        private void ModifyGrid()
        {
            if (gvData.Columns[STA_Partner.C_id] == null)
                return;
            if (gvData.Columns[STA_Partner.C_id].ColumnEdit == null || bolIsRefresh)
                CRM_PartnerService.InitRepositoryLookUpEdit(gvData, STA_Partner.C_id);
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = new STA_Partner().Search();
                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "STA_Partner", bolIsRefresh);
                    ModifyGrid();
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        /// <summary>
        /// Xóa từng dòng được chọn, bị lỗi chỗ nào thì ngưng chỗ ấy lại
        /// </summary>
        /// <returns></returns>
        private bool DeleteData()
        {
            STA_Partner obj = new STA_Partner();
            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = arrRowIndex.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null)
                {
                    if (drw.RowState != DataRowState.Added)
                    {
                        if (!obj.Delete(Convert.ToString(drw[STA_Partner.C_ten])))
                        {
                            ErrorManager.Error("Dữ liệu đang sử dụng bạn không xóa được!");
                            return false;
                        }
                    }
                    gvData.DeleteRow(arrRowIndex[i]);
                }
            }
            return true;
        }

        /// <summary>
        /// Save dữ liệu ở lưới
        /// </summary>
        private bool SaveData()
        {
            if (dtbData != null)
            {
                STA_Partner item0 = new STA_Partner();
                item0.BeginTransaction();
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (drw.RowState != DataRowState.Deleted)
                    {
                        STA_Partner item = new STA_Partner();
                        item.IDB = item0.IDB;
                        if (item.Parse(drw))
                        {
                            if (drw.RowState == DataRowState.Added)
                            {
                                if (!item.Add())
                                {
                                    ErrorManager.Error("Việc thêm thông tin bị lỗi!");
                                    return false;
                                }
                            }
                            else if (drw.RowState == DataRowState.Modified)
                            {
                                if (!item.Update())
                                {
                                    ErrorManager.Error("Việc cập nhật thông tin bị lỗi!");
                                    return false;
                                }
                            }
                        }
                    }
                }
                item0.CommitTransaction();
                return true;
            }
            return true;
        }

        private string CheckValidate(DataRow drw)
        {
            if (drw == null)
                return "";
            STA_Partner item = new STA_Partner();
            if (item.Parse(drw))
            {
                if (item.Ten == "" || item.Ten == null)
                    return "Bạn phải nhập tên khách trạm!";
            }
            return "";
        }

        /// <summary>
        /// Chọn nhiều dòng -> chuột phải Chọn khách -> gán cùng 1 CRM_Partner.PartnerID
        /// </summary>
        private void ApplyPartnerToSelectedRows()
        {
            if (gvData.SelectedRowsCount <= 0)
            {
                MessageManager.Warning("Bạn phải chọn ít nhất một dòng!");
                return;
            }
            if (!UserSession.HasPermission(PERMISSION_EDIT))
            {
                MessageManager.Warning("Bạn không có quyền cập nhật!");
                return;
            }

            CRMManager.Declaration.Partner.frmPartnerSelect frm = CRMManager.Declaration.Partner.frmPartnerSelect.Instance;
            frm.ISMultiSelect = false;
            frm.ShowDialog();
            if (!frm.IsOk || frm.ItemSelected == null || frm.ItemSelected.PartnerID == null)
                return;

            int intPartnerID = Convert.ToInt32(frm.ItemSelected.PartnerID);
            string strPartnerCode = frm.ItemSelected.PartnerCode;
            string strPartnerName = frm.ItemSelected.PartnerName;

            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = 0; i < arrRowIndex.Length; i++)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null && drw.RowState != DataRowState.Deleted)
                {
                    drw[STA_Partner.C_id] = intPartnerID;
                    if (dtbData.Columns.Contains("PartnerCode"))
                        drw["PartnerCode"] = strPartnerCode;
                    if (dtbData.Columns.Contains("PartnerName"))
                        drw["PartnerName"] = strPartnerName;
                }
            }

            btnSave.Enabled = mnuItemSave.Enabled = true;
            gvData.RefreshData();
            MessageManager.Info(String.Format("Đã gán khách hàng [{0}] cho {1} dòng. Bấm Lưu để cập nhật.", strPartnerName, arrRowIndex.Length));
        }

        private void UpdateSelectPartnerMenu()
        {
            mnuItemSelectPartner.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_EDIT);
        }

        #endregion

