# Fix double-spaced SQL files by removing blank line after every content line
function Fix-DoubleSpacedFile($path) {
  $lines = [System.IO.File]::ReadAllLines($path)
  # Detect: majority of non-blank lines followed by blank
  $pairs = 0; $checked = 0
  for ($i=0; $i -lt $lines.Count-1; $i++) {
    if (-not [string]::IsNullOrWhiteSpace($lines[$i])) {
      $checked++
      if ([string]::IsNullOrWhiteSpace($lines[$i+1])) { $pairs++ }
    }
  }
  if ($checked -eq 0 -or ($pairs * 1.0 / $checked) -lt 0.8) {
    Write-Output "SKIP (not double-spaced): $path ($pairs/$checked)"
    return
  }
  $out = New-Object System.Collections.Generic.List[string]
  for ($i=0; $i -lt $lines.Count; $i++) {
    if ([string]::IsNullOrWhiteSpace($lines[$i])) { continue }
    $out.Add($lines[$i])
    # Keep intentional blank before GO / comment blocks: add blank after GO
    if ($lines[$i].Trim() -eq 'GO' -or $lines[$i].Trim().StartsWith('/*')) {
      # peek: if next non-blank exists, insert one blank after GO or before next section after comment end
    }
  }
  # Rebuild with light formatting: blank line after GO
  $final = New-Object System.Collections.Generic.List[string]
  foreach ($line in $out) {
    $final.Add($line)
    if ($line.Trim() -eq 'GO') { $final.Add('') }
  }
  [System.IO.File]::WriteAllLines($path, $final)
  Write-Output "FIXED: $path ($($lines.Count) -> $($final.Count))"
}
